int *mergeSort(int *array, int length) {
    if(length <= 1) {
        return array;
    }
    int *head = split(array, 0, length / 2);
    int *tail = split(array, length / 2, length);
    return merge(mergeSort(head, length / 2), mergeSort(tail, length - length / 2), length / 2, length - length / 2);
}

int *split(int *array, int start, int end) {
    int *newArray = (int *)malloc(sizeof(int) * (end - start));
    for(int i = start, j = 0; i < end; i++, j++) {
        newArray[j] = array[i];
    }
    return newArray;
}

int *merge(int *a, int *b, int aLength, int bLength) {
    int *merged = (int *)malloc(sizeof(int) * (aLength + bLength));
    for(int i = 0, j = 0, k = 0; i < aLength + bLength; i++) {
        if(j == aLength || k == bLength) {
            merged[i] = (j == aLength ? b[k++] : a[j++]);
        } else {
            merged[i] = (a[j] > b[k] ? a[j++] : b[k++]);
        }
    }
    return merged;
}

