#import <Foundation/Foundation.h>
#import <CoreFoundation/CoreFoundation.h>

double** createMatrix(int rows, int cols) {
    double** matrix = (double**)malloc(rows * sizeof(double*));
    for (int i = 0; i < rows; i++) {
        matrix[i] = (double*)malloc(cols * sizeof(double));
    }
    return matrix;
}

void freeMatrix(double** matrix, int rows) {
    for (int i = 0; i < rows; i++) {
        free(matrix[i]);
    }
    free(matrix);
}

double* gaussJordan(double** A, double* b, int n) {
    double** B = createMatrix(n, n+1);
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            B[i][j] = A[i][j];
        }
        B[i][n] = b[i];
    }

    for (int v = 0; v < n; v++) {
        int pivot = v;
        for (int r = v; r < n; r++) {
            if (fabs(B[r][v]) > fabs(B[pivot][v])) {
                pivot = r;
            }
        }

        double* tmp = B[v];
        B[v] = B[pivot];
        B[pivot] = tmp;

        for (int c = v+1; c < n+1; c++) {
            B[v][c] /= B[v][v];
        }
        for (int r = 0; r < n; r++) {
            if (r == v) continue;
            for (int c = v+1; c < n+1; c++) {
                B[r][c] -= B[v][c] * B[r][v];
            }
        }
    }

    double* res = (double*)malloc(n * sizeof(double));
    for (int i = 0; i < n; i++) {
        res[i] = B[i][n];
    }
    freeMatrix(B, n);
    return res;
}

int main() {
    NSAutoreleasePool *pool = [[NSAutoreleasePool alloc] init];

    NSInputStream *inputStream = [NSInputStream inputStreamWithFileAtPath:@"/dev/stdin"];
    [inputStream open];

    NSMutableData *data = [NSMutableData data];
    while ([inputStream hasBytesAvailable]) {
        uint8_t buffer[1024];
        NSInteger bytesRead = [inputStream read:buffer maxLength:sizeof(buffer)];
        if (bytesRead > 0) {
            [data appendBytes:(const void *)buffer length:bytesRead];
        }
    }

    [inputStream close];

    NSString *inputString = [[NSString alloc] initWithData:data encoding:NSUTF8StringEncoding];
    NSArray *lines = [inputString componentsSeparatedByString:@"\n"];

    for (NSString *line in lines) {
        if ([line length] == 0) continue;

        NSArray *components = [line componentsSeparatedByString:@" "];
        int n = components.count / 3;
        double** A = createMatrix(n, n);
        double* b = (double*)malloc(n * sizeof(double));

        for (int i = 0; i < n; i++) {
            A[i][0] = [components[i*3] doubleValue];
            A[i][1] = [components[i*3+1] doubleValue];
            b[i] = [components[i*3+2] doubleValue];
        }

        double* x = gaussJordan(A, b, n);

        NSLog(@"%.3f %.3f", x[0], x[1]);

        free(x);
        freeMatrix(A, n);
        free(b);
    }

    [inputString release];
    [pool drain];
    return 0;
}

