	public static int[] yakusu(int a){
		int[] l =new int[(int)Math.sqrt((double)a)+1];
		int counta=0;
		for(int i=2;i<=a;i++){
			if(a%i==0){
				l[counta]=i;
				counta++;
				a=a/i;
				i--;
			}
		}
		int[] y=new int[counta];
		for(int j=0;j<counta;j++){
			y[j]=l[j];
		}
		return y;
	}

	public static boolean sosu(int a){
		for(int j=2;j<=a;j++){
			if(a==j){
				return true;
			}else if(a%j==0)return false;
		}
		return false;
	}
	public static int[] kobaisu(int[] a,int[] b){
		int[] n= {1,1};
		int j=0,i=0;

		while(i<a.length&&j<b.length){
			if(a[i]==b[j]){
				n[0]=n[0]*a[i];
				n[1]=n[1]*a[i];
				i++;j++;
			}else if(a[i]>b[j]){
				n[0]=n[0]*b[j];
				j++;		
			}else if(a[i]<b[j]){
				n[0]=n[0]*a[i];
				i++;
			}
		}
		while(i<a.length){
			n[0]=n[0]*a[i];
			i++;
		}
		while(j<b.length){
			n[0]=n[0]*b[j];
			j++;
		}
		return n;
	}
}

