    String readStr;
    int[] numPatternCount = new int[19];
    int i, j, k, l;
    int size = 9;
    int sum;
    for (i = 0; i <= size; i++) {
      for (j = 0; j <= size; j++) {
        if (i+j > 18)
              break;
        for (k = 0; k <= size; k++) {
          if (i+j+k > 18)
              break;
          for (l = 0; l <= size; l++) {
            sum = i + j + k + l;
            if (sum > 18)
              break;
            numPatternCount[sum]++;
          }
        }
      }
    }
    while ((readStr = reader.readLine()) != null) {
      int n = Integer.parseInt(readStr);
      System.out.println(
              n > 36 ? 0
              : numPatternCount[n > 18 ? numPatternCount.length - (n - numPatternCount.length) - 2 : n]
      );
    }
  }

}

