				if(!map.containsKey(i+j))
					map.put(i+j, 1);
				else
					map.put(i+j, map.get(i+j)+1);
			}
		}

		BufferedReader bf = new BufferedReader(new InputStreamReader(System.in));
		String str;

		try{
			while((str = bf.readLine()) != null){
				int ans = 0;
