            xy23 = x2 * x2 - x3 * x3 + y2 * y2 - y3 * y3;

            py = (x23 * xy12 - x12 * xy23) / (x12 * y23 - x23 * y12);
            px = (y12 * xy23 - y23 * xy12) / (x12 * y23 - x23 * y12);

            r = sqrt(pow(x1 - px, 2) + pow(y1 - py, 2));

            printf("%.3f %.3f %.3f\n", px, py, r);
        }
