    double b2 = 2 * (y3 - y1);
    double c2 = (x1 * x1) - (x3 * x3) + (y1 * y1) - (y3 * y3);

    double numerator = b1 * c2 - b2 * c1;
    double denominator = a1 * b2 - a2 * b1;

    return numerator / denominator;
}

double getPointY(double x1, double y1, double x2, double y2, double x3, double y3) {
    double a1 = 2 * (x2 - x1);
    double b1 = 2 * (y2 - y1);
