            [resultsX addObject:@(pointX)];

            double pointY = getPointY(x1, y1, x2, y2, x3, y3);
            [resultsY addObject:@(pointY)];

            double radius = getDistance(x1, y1, pointX, pointY);
            [resultsRadius addObject:@(radius)];
