@implementation HorizontalLine

- (instancetype)initWithLeft:(int)left right:(int)right {
    self = [super init];
    if (self) {
        _left = left;
        _right = right;
    }
    return self;
}

- (int)jumpIfOnThisLine:(int)value {
    if (value == _right) {
        return _left;
    }
    else if (value == _left) {
        return _right;
    }
    return value;
}

