#import <Foundation/Foundation.h>

int judge(double x[], double y[], double p[]) {
    double a = 0;
    if (x[0] != y[0]) {
        a = ((y[1]-x[1])/(y[0]-x[0]))*(p[0]-x[0])+x[1];
    }
    if (x[0] == y[0]) {
        if (p[0] < x[0]) {
            return -1;
        } else {
            return 1;
        }
    }
    if (a < p[1]) {
        return 1;
    } else {
        return -1;
    }
}

NSString* solve(double x[][2], double p[]) {
    for (int i = 0; i < 3; i++) {
        int max = i;
        for (int j = i+1; j < 3; j++) {
            if (x[j][0] > x[max][0] || (x[j][0] == x[max][0] && x[j][1] < x[max][1])) {
                max = j;
            }
        }
        double tempX = x[max][0];
        double tempY = x[max][1];
        x[max][0] = x[i][0];
        x[max][1] = x[i][1];
        x[i][0] = tempX;
        x[i][1] = tempY;
    }
    if (p[0] > x[0][0] || p[0] < x[2][0]) {
        return @"NO";
    }
    int key = judge(x[0], x[2], p);
    if (key*judge(x[0], x[1], p) < 0 && key*judge(x[1], x[2], p) < 0) {
        return @"YES";
    } else {
        return @"NO";
    }
}

