+ (void)mergeSort:(NSMutableArray *)array left:(NSInteger)l right:(NSInteger)r {
    if (l+1 == r) return;

    NSInteger m = (l+r) / 2;
    [self mergeSort:array left:l right:m];
    [self mergeSort:array left:m right:r];
    [self merge:array left:l middle:m right:r];
}

+ (void)merge:(NSMutableArray *)array left:(NSInteger)l middle:(NSInteger)m right:(NSInteger)r {
    NSMutableArray *sorted = [NSMutableArray arrayWithCapacity:r-l];
    NSInteger i = l;
    NSInteger j = m;
    NSInteger k = 0;
    while (k < r-l) {
        if (i == m) {
            [sorted addObject:[array objectAtIndex:j]];
            j++;
        } else if (j == r) {
            [sorted addObject:[array objectAtIndex:i]];
            i++;
        } else if ([[array objectAtIndex:i] intValue] < [[array objectAtIndex:j] intValue]) {
            [sorted addObject:[array objectAtIndex:j]];
            j++;
        } else {
            [sorted addObject:[array objectAtIndex:i]];
            i++;
        }
        k++;
    }

    for (NSInteger index=0; index < r-l; index++) {
        [array replaceObjectAtIndex:l+index withObject:[sorted objectAtIndex:index]];
    }
}

