+ (void)merge:(NSMutableArray *)array left:(NSInteger)l middle:(NSInteger)m right:(NSInteger)r {
    NSMutableArray *sorted = [NSMutableArray arrayWithCapacity:r-l];
    NSInteger i = l;
    NSInteger j = m;
