		switch (m) {
		case 2:
			return sumofdays(m-1) + 29;
		case 4:
		case 6:
		case 9:
		case 11:
			return sumofdays(m-1) + 30;
		default:
			return sumofdays(m-1) + 31;
		}
	}


	public static int sumofdays(int m, int d) {
		return sumofdays(m-1) + d;
	}

	public static String yoobi(int d) {
		int r = d % 7;
		switch (r) {
		case 1:
			return "Thursday";
		case 2:
			return "Friday";
		case 3:
			return "Saturday";
		case 4:
			return "Sunday";
		case 5:
			return "Monday";
		case 6:
			return "Tuesday";
		default :
			return "Wednesday";
		}
	}
}

