			P[] p=new P[4];
			for(int i=0;i<8;i=i+2){
				double a = Double.parseDouble(s[i]);
				double b = Double.parseDouble(s[i+1]);
				p[i/2]=new P(a,b);
			}
			P[] con=Main.convexHull(p);
			if(con.length<4){
				System.out.println("NO");
