class XPoint{

	private double x;
	private double y;

	public double getX(){
		return this.x;
	}

	public double getY(){
		return this.y;
	}

	public XPoint(double d, double e){
		this.x = d;
		this.y = e;
	}
}

class XLine{

	double p;
	double q;
	double r;








	XLine(double p, double q, double r){
		this.p = p;
		this.q = q;
		this.r = r;
	}

	public XLine(XPoint p1, XPoint p2){

		if(p1.getX() != p2.getX()) {
			this.p = -(p1.getY()-p2.getY())/(p1.getX()-p2.getX());
			this.q = 1;
			this.r = p1.getX()* this.p +p1.getY();
		}else {
			if(p1.getY() != p2.getY()) {
				this.p = 1;
				this.q = 0;
				this.r = 0;
			}else {
				this.p = 1;
				this.q = 1;
				this.r = 1;
			}
		}
	}








	boolean isTheSameSide(XPoint x, XPoint y){
		double result = (this.calcPX_QY(x.getX(), x.getY()) - this.r)
				* (this.calcPX_QY(y.getX(), y.getY()) - this.r);
		return (result > 0) ? true: false;
	}








	double calcPX_QY(double x, double y){
		return x * p + y * q;
	}
}

class XTriangle{

	XPoint p1;
	XPoint p2;
