        line[i] = false;
      }
      else {
        line[i] = true;
      }
    }
    return line;
  }

  public static int[] check(boolean[] line){
    for (int i = 0; i < 8; i++) {
      if (line[i]) {
        if (i < 7 && line[i+1]) {
          if (i < 6 && line[i+2]) {
            int[] check = {i,3};
            return check;
          }
          else {
            int[] check = {i,2};
            return check;
          }
        }
        else {
            int[] check = {i,1};
            return check;
        }
      }
    }
    int[] check = {0,0};
    return check;
  }

  public static void main(String[] args){
    Scanner sc = new Scanner(System.in);
    while(sc.hasNext()) {
      String str = sc.next();
      int[] chk1 = check(lineSet(str));
      if(chk1[1] == 0) {
        continue;
      }
      else if (chk1[1] == 3) {
        System.out.println("C");
        continue;
      }
      else {
        str = sc.next();
        int[] chk2 = check(lineSet(str));
        if (chk1[1] == 1) {
          if (chk2[1] == 1) {
            System.out.println("B");
