            for (int i = 0; i < 8; i++) {
                String text = sc.next();
                for (int j = 0; j < 8; j++) {
                    if (text.charAt(j) == '1') {
                        if (sum == 0) {
                            offsetX = j;
                            offsetY = i;
                            sum++;
                        } else {
                            int dx = j - offsetX;
                            int dy = i - offsetY;
                            if (dx >= 0) {
                                sum += check[dy][dx];
                            }
                        }
                    }
                }
            }
            char answer = 0;
            switch (sum) {
