import java.util.Scanner;

public class Main {

	public static final char cDir[] = {
		'U', 'R', 'D', 'L'
	};

	public static final int pDir[][] = {
		{0, -1}, {1, 0}, {0, 1}, {-1, 0}
	};



	public static void main(String[] args) {

		Scanner scan = new Scanner(System.in);

		while(scan.hasNext()){
			char map[][] = new char [9][5];
			boolean neighbor[][][] = new boolean [5][5][4];
			int hand[] = {0, 0};	
			int iDir = 1;			
			String answer = new String();


			for(int i=0; i<9; i++){
				map[i] = scan.next().toCharArray();
			}


			for(int i=0; i<5; ++i){
				for(int j=0; j<5; ++j){

					neighbor[i][j][0] = 0<=(i*2-1) ? (map[i*2 -1][j] == '1') : false;

					neighbor[i][j][1] = j<(5-1) ? (map[i*2][j] == '1') : false;

					neighbor[i][j][2] = (i*2+1)<9 ? (map[i*2+1][j] == '1') : false;

					neighbor[i][j][3] = 0<=(j-1) ? (map[i*2][j-1] == '1') : false; 
				}
			}


			int x=0, y=0;
			while(true){

				x = hand[0]; y = hand[1];
				if(neighbor[y][x][(iDir+3)%4]){
					iDir = (iDir+3)%4;
				}else if(neighbor[y][x][(iDir+0)%4]){
					iDir = (iDir+0)%4;
				}else if(neighbor[y][x][(iDir+1)%4]){
					iDir = (iDir+1)%4;
				}else{
					iDir = (iDir+2)%4;	
				}


				hand[0] += pDir[iDir][0];
				hand[1] += pDir[iDir][1];
				answer += cDir[iDir];

				if(hand[0]==0 && hand[1]==0){
					break;
				}
			}
			System.out.println(answer);
		}
	}
}

import java.util.*;

public class Main{

	private void doit(){
		Scanner sc = new Scanner(System.in);
		int mapsize = 9;
		while(sc.hasNext()){
			int [][] pass = new int[mapsize][mapsize];
			for(int i = 0; i < mapsize; i++){
				String s = sc.next();
				if(i % 2 == 0){
					Arrays.fill(pass[i], 1);
					for(int j = 0; j < 4; j++){
						int c = s.charAt(j) - '0';
						pass[i][j * 2 + 1] = c;
					}
				}
				else{
					for(int j = 0; j < 5; j++){
						int c = s.charAt(j) - '0';
						pass[i][j * 2] = c;
					}
				}
			}

			int [] vx = {-1,0,1,0};
			int [] vy = {0,-1,0,1};
			String [] word = {"L", "U", "R", "D"};
			int nowx = 0, nowy = 0;
			int dir = 2;
			StringBuilder sb = new StringBuilder();
			while(true){
				for(int i = 3; i < 7; i++){
					int xx = nowx + vx[(i + dir) % 4];
					int yy = nowy + vy[(i + dir) % 4];
					int xxx = xx + vx[(i + dir) % 4];
					int yyy = yy + vy[(i + dir) % 4];
					if(! isOK(xx, yy, mapsize)) continue;
					if(! isOK(xxx, yyy, mapsize)) continue;
					if(pass[yy][xx] == 0) continue;
					if(pass[yyy][xxx] == 0) continue;
					nowx = xxx;
					nowy = yyy;
					dir = (i + dir) % 4;
					sb.append(word[(dir)]);
					break;
				}
				if(nowx == 0 && nowy == 0){
					break;
				}
			}
			System.out.println(sb.toString());
		}
	}

	private boolean isOK(int x,int y,int mapsize){
		if(0 <= x && x < mapsize && 0 <= y && y < mapsize){
			return true;
		}
		return false;
	}

	public static void main(String[] args) {
		new Main().doit();
	}
}

import java.util.*;

class Main{
  static boolean[][] wall = new boolean[9][];
  static int[] point = {0,0,0};

  public static boolean[] lineSet(String str){
    boolean[] line = new boolean[str.length()];
    for (int i = 0; i < str.length(); i++) {
      if (str.charAt(i) == '0') {
        line[i] = false;
      }
      else {
        line[i] = true;
      }
    }
    return line;
  }

  public static void moveR(){
    System.out.print("R");
    point[1]++;
    point[2] = 0;
  }

  public static void moveD(){
    System.out.print("D");
    point[0] += 2;
    point[2] = 1;
  }

  public static void moveL(){
    System.out.print("L");
    point[1]--;
    point[2] = 2;
  }

  public static void moveU(){
    System.out.print("U");
    point[0] -= 2;
    point[2] = 3;
  }

  public static void directionR(){
    if (point[0] > 0 && wall[point[0]-1][point[1]]) {
      moveU();
    }
    else if (point[1] < 4 && wall[point[0]][point[1]]) {
      moveR();
    }
    else if (point[0] < 8 && wall[point[0]+1][point[1]]) {
      moveD();
    }
    else {
      moveL();
    }
  }
  public static void directionD(){
    if (point[1] < 4 && wall[point[0]][point[1]]) {
      moveR();
    }
    else if (point[0] < 8 && wall[point[0]+1][point[1]]) {
      moveD();
    }
    else if (point[1] > 0 && wall[point[0]][point[1]-1]) {
      moveL();
    }
    else {
      moveU();
    }
  }
  public static void directionL(){
    if (point[0] < 8 && wall[point[0]+1][point[1]]) {
      moveD();
    }
    else if (point[1] > 0 && wall[point[0]][point[1]-1]) {
      moveL();
    }
    else if (point[0] > 0 && wall[point[0]-1][point[1]]) {
      moveU();
    }
    else {
      moveR();
    }
  }
  public static void directionU(){
    if (point[1] > 0 && wall[point[0]][point[1]-1]) {
      moveL();
    }
    else if (point[0] > 0 && wall[point[0]-1][point[1]]) {
      moveU();
    }
    else if (point[1] < 4 && wall[point[0]][point[1]]) {
      moveR();
    }
    else {
      moveD();
    }
  }

  public static void direction(){
    switch(point[2]) {
      case 0:
        directionR();
        break;
      case 1:
        directionD();
        break;
      case 2:
        directionL();
        break;
      case 3:
        directionU();
    }
  }

  public static void main(String[] args){
    Scanner sc = new Scanner(System.in);
    for (int i = 0; i < 9; i++) {
      String str = sc.next();
      wall[i] = lineSet(str);
    }
    while(true) {
      direction();
      if (point[0] == 0 && point[1] == 0) {
        break;
      }
    }
    System.out.println("");
  }
}

