#import <Foundation/Foundation.h>

@interface RomanFigure : NSObject

@property (nonatomic, assign) int arabicNumber;

- (instancetype)initWithRomanNumeral:(NSString *)romanNumeral;
- (int)toArabic;

@end

@implementation RomanFigure

- (instancetype)initWithRomanNumeral:(NSString *)romanNumeral {
    if (self = [super init]) {
        if ([romanNumeral length] == 0) {
            self.arabicNumber = 0;
        } else {
            int tmpArabicNumber = 0;
            for (int i = 0; i < [romanNumeral length];) {
                unichar letter = [romanNumeral characterAtIndex:i];
                int number = [self letterToNumber:letter];
                if (number < 0) {
                    self.arabicNumber = 0;
                    break;
                } else {
                    i++;
                    if (i == [romanNumeral length]) {
                        tmpArabicNumber += number;
                    } else {
                        unichar nextLetter = [romanNumeral characterAtIndex:i];
                        int nextNumber = [self letterToNumber:nextLetter];
                        if (nextNumber > number) {
                            tmpArabicNumber += (nextNumber - number);
                            i++;
                        } else {
                            tmpArabicNumber += number;
                        }
                    }
                }
            }
            self.arabicNumber = tmpArabicNumber;
        }
    }
    return self;
}

- (int)toArabic {
    return self.arabicNumber;
}

- (int)letterToNumber:(unichar)letter {
    switch (letter) {
        case 'I': return 1;
        case 'V': return 5;
        case 'X': return 10;
        case 'L': return 50;
        case 'C': return 100;
        case 'D': return 500;
        case 'M': return 1000;
        default: return -1;
    }
}

@end

