					if(10%(input[i]*input[j]) == 0){
						tmpResult = makeExpression(tmpIntArray, 10 / input[i]*input[j]);
						if(tmpResult != null){
							result = "("+tmpResult + " * ("+ input[i] + " * " + input[j]+"))";
