				LinkedList<Term> copy = new LinkedList<>(e);
				HashSet< LinkedList<Term> > temp = calc(copy);
				after.addAll(new HashSet<LinkedList<Term>>(temp));
			}
			before = after;
			after = new HashSet<>();
		}

		for (LinkedList<Term> e : before) {
