						}
					}

					for (int k = 0 ; k < 4 ; k++) {
						expr = new String[7];
						for (int l = 0 ; l < 7 ; l++) expr[l] = terms[table_pattern[k][l]];



						if (10 == calcRPN(expr)) {

							isFound = true;
							break LOOP;
						}
					}
