import java.util.Scanner;

public class Main {
	MyScanner sc = new MyScanner();
	Scanner sc2 = new Scanner(System.in);
	final int MOD = 1000000007;
	int[] dx = { 1, 0, 0, -1 };
	int[] dy = { 0, 1, -1, 0 };

	void run() {
		int T = 1;
		for (;;) {
			int W = sc.nextInt();
			if (W == 0) {
				return;
			}
			int N = sc.nextInt();
			int[] p = new int[N];
			int[] w = new int[N];
			int[][] dp = new int[N + 1][W + 1];
			for (int i = 0; i < N; i++) {
				String[] in = sc.next().split(",");
				p[i] = Integer.valueOf(in[0]);
				w[i] = Integer.valueOf(in[1]);
			}
			for (int i = N - 1; i >= 0; i--) {
				for (int j = 0; j <= W; j++) {
					if (j - w[i] < 0) {
						dp[i][j] = dp[i + 1][j];
					} else {
						dp[i][j] = Math.max(dp[i + 1][j], dp[i + 1][j - w[i]]
								+ p[i]);
					}
				}
			}
			System.out.println("Case " + T++ + ":");
			int maxP = 0;
			int maxW = 0;
			for (int i = 0; i <= W; i++) {
				if (maxP < dp[0][i]) {
					maxP = dp[0][i];
					maxW = i;
				}
			}
			System.out.println(maxP);
			System.out.println(maxW);
		}
	}

	public static void main(String[] args) {
		new Main().run();
	}

	void debug(Object... o) {
		System.out.println(Arrays.deepToString(o));
	}

	void debug2(int[][] array) {
		for (int i = 0; i < array.length; i++) {
			for (int j = 0; j < array[i].length; j++) {
				System.out.print(array[i][j]);
			}
			System.out.println();
		}
	}

	boolean inner(int h, int w, int limH, int limW) {
		return 0 <= h && h < limH && 0 <= w && w < limW;
	}

	void swap(int[] x, int a, int b) {
		int tmp = x[a];
		x[a] = x[b];
		x[b] = tmp;
	}


	int lower_bound(int a[], int border) {
		int l = -1;
		int r = a.length;

		while (r - l > 1) {
			int mid = (l + r) / 2;
			if (border <= a[mid]) {
				r = mid;
			} else {
				l = mid;
			}
		}

		return r;
	}

