		int d[];
		String st;
		boolean flag;

		a = new int[13];
		b = new int[14];
		c = new int[12];
		d = new int[10];
		while (sc.hasNext()) {
			st = sc.next();
			for (int i = 0; i < 13; i++) {
				a[i] = st.charAt(i) - '0';
			}
			for (int i = 1; i <= 9; i++) {
				flag = false;
				b[0] = i;
				d[i] = 0;
				for (int j = 0; j < 13; j++) {
					b[j + 1] = a[j];
				}
				sort(b);
				if (!isNotFifth(b)) {
					continue;
				}
				int head = 0;
				for (int j = 0; j < 13; j++) {
					if (b[j] == b[j + 1] && head < b[j]) {
						int index = 0;
						head = b[j];
						for (int k = 0; k < 14; k++) {
							if (k != j && k != j + 1) {
								c[index++] = b[k];
							}
						}
						if (check(c)) {
							flag = true;
						}
					}
				}
				if (flag) {
					d[i] = 1;
				}
			}
			String s = "";
			for (int i = 1; i <= 9; i++) {
				if (d[i] == 1) {
