	    ArrayList<Character> res = new ArrayList<Character>();
	    for(char lastChar='1';lastChar<='9';lastChar++){
		if(freq[lastChar] >= 4) continue;
		ArrayList<Character> e  = new ArrayList<Character>(tmp_e);
