			    if(fillShuntsu(e,visited)){
				res.add(lastChar);

				break;
			    }
			}
		    }


		}
	    }

	    show(res);
	}
    }

    void show(ArrayList<Character> e){
	Collections.sort(e);
	int[] freq = new int[255];
	ArrayList<Character> res = new ArrayList<Character>();

	for(int i=0;i<e.size();i++){
	    if(freq[e.get(i)] > 0) continue;
	    freq[e.get(i)]++;
	    res.add(e.get(i));
	}

	if(res.size() == 0){
	    System.out.println(0);
	    return;
	}

