    void printBitArray(ArrayList<Integer> e,int w){
	for(int i=0;i<e.size();i++){
	    printBit(e.get(i),w);
	}
    }
    void printBit(int num,int w){
	for(int i=0;i<w;i++){
	    if((num & (1<<i)) > 0){
		System.out.print("1");
	    }
	    else{
		System.out.print("0");
	    }
	}
