    ArrayList<Integer> findJanto(ArrayList<Character> e,int visited){
	ArrayList<Integer> res = new ArrayList<Integer>();
	for(int base=1;base<=9;base++){
	    for(int i=0;i+1<e.size();i++){
		int tmp = visited;
		if(e.get(i) == base + '0'
		   && e.get(i+1) == base + '0'){
		    tmp |= (1<<i);
		    tmp |= (1<<(i+1));
		    res.add(tmp);

		}
	    }
	}


	return res;
    }

    boolean isIntersect(ArrayList<Integer> e,int width){
	for(int i=0;i<e.size();i++){
	    for(int j=i+1;j<e.size();j++){
		for(int k=0;k<width;k++){
		    int a = e.get(i);
		    int b = e.get(j);

		    if(((a & (1<<k))
			& (b & (1<<k))) > 0){
			return true;
		    }
		}
	    }
	}
	return false;
    }

    ArrayList<Integer> findKotsu(ArrayList<Character> e,int visited){
	ArrayList<Integer> res = new ArrayList<Integer>();
	for(int base=1;base<=9;base++){
	    for(int i=0;i+2<e.size();i++){
		if((
		    (visited & (1<<i))
		    | (visited & (1<<(i+1)))
		    | (visited & (1<<(i+2)))
		    ) > 0) continue;
		int tmp = 0;
		if(e.get(i) == base + '0'
		   && e.get(i+1) == base + '0'
		   && e.get(i+2) == base + '0'){
		    tmp |= (1<<i);
		    tmp |= (1<<(i+1));
		    tmp |= (1<<(i+2));
		    res.add(tmp);

		}
	    }

	}
	return res;
    }

    boolean fillShuntsu(ArrayList<Character> e,int visited){

	for(int i=0;i<e.size();i++){
	    int count = 0;
	    if((visited & (1<<i)) > 0) continue;
	    int tmp = visited;
	    int first = e.get(i);
	    count++;
	    tmp |= (1<<i);
	    for(int j=i+1;j<e.size();j++){
		if((visited & (1<<j)) > 0) continue;
		if(first + 1 == e.get(j)
		   && (tmp & (1<<j)) == 0
		   && count == 1){
		    tmp |= (1<<j);
		    count++;
		}
		if(first + 2 == e.get(j)
		   && (tmp & (1<<j)) == 0
		   && count == 2){
		    tmp |= (1<<j);
		    count++;
		    break;

		}
		if(first + 2 < e.get(j)){
		    count = 0;
		    break;
		}
	    }

	    if(count == 3){
		visited = tmp;
	    }
	}

	return (visited == ((1<<14)-1));
    }

