int bs_upper(NSArray *p, int k) {
    int l = -1;
    int r = [p count];
    int mid = 0;
    while(r - l > 1) {
        mid = l + (r - l) / 2;
        if([p[mid] intValue] > k) {
            r = mid;
        }else {
            l = mid;
        }
    }
    return r;
}

int bs_lower(NSArray *p, int k) {
    int l = -1;
    int r = [p count];
    int mid = 0;
    while(r - l > 1) {
        mid = l + (r - l) / 2;
        if([p[mid] intValue] < k) {
            l = mid;
        }else {
            r = mid;
        }
    }
    return l;
}

