	}
	static String solve(Deque<String[]> que) {
		String now = "A";
		while(!que.isEmpty()) {
			String[] pair = que.pollLast();
			now = now.equals(pair[0])?pair[1]:now.equals(pair[1])?pair[0]:now;
		}
		return now;
	}
