	public static void main(String[] args) {
		FastScanner sc = new FastScanner();
		PrintWriter out = new PrintWriter(System.out);
		while(sc.hasNext()) {
			int n = (int)sc.nextLong();
			out.println((n*n+n+2)/2);
		}
		out.flush();
