		PrintWriter out = new PrintWriter(System.out);
		while(sc.hasNext()) {
			double x1 = Double.parseDouble(sc.next());
			double y1 = Double.parseDouble(sc.next());
			double x2 = Double.parseDouble(sc.next());
			double y2 = Double.parseDouble(sc.next());
			double x3 = Double.parseDouble(sc.next());
			double y3 = Double.parseDouble(sc.next());
			double x4 = Double.parseDouble(sc.next());
			double y4 = Double.parseDouble(sc.next());

			x2 -= x1;
			y2 -= y1;
			x4 -= x3;
			y4 -= y3;

			double cr = x2*x4 + y2*y4;
			if(Math.abs(cr) <= 1.0e-10) {
				out.println("YES");
			}
			else {
				out.println("NO");
			}
		}
		out.flush();
	}
}



class FastScanner {
    private final InputStream in = System.in;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int buflen = 0;
    private boolean hasNextByte() {
        if (ptr < buflen) {
            return true;
        }else{
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            if (buflen <= 0) {
                return false;
            }
        }
        return true;
    }
    private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
    private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
    private void skipUnprintable() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++;}
    public boolean hasNext() { skipUnprintable(); return hasNextByte();}
    public String next() {
        if (!hasNext()) throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        int b = readByte();
        while(isPrintableChar(b)) {
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }
    public long nextLong() {
        if (!hasNext()) throw new NoSuchElementException();
        long n = 0;
        boolean minus = false;
        int b = readByte();
        if (b == '-') {
            minus = true;
            b = readByte();
        }
        if (b < '0' || '9' < b) {
            throw new NumberFormatException();
        }
        while(true){
            if ('0' <= b && b <= '9') {
                n *= 10;
                n += b - '0';
            }else if(b == -1 || !isPrintableChar(b)){
                return minus ? -n : n;
            }else{
                throw new NumberFormatException();
            }
            b = readByte();
        }
    }
}

