class Comp implements Comparator<Data>{

	@Override
	public int compare(Data o1, Data o2) {
		if(o1.point > o2.point) {
			return -1;
		}
		else if(o1.point < o2.point) {
			return 1;
		}
		else if(o1.id > o2.id) {
			return 1;
		}
		else if(o1.id < o2.id) {
			return -1;
		}
