import java.util.*;
import java.io.*;

class Main {

    public static void main( String[] args ) {

	final Scanner stdin = new Scanner( System.in );

	while ( stdin.hasNextLine() ) {
	    final String input = stdin.nextLine();

	    final boolean winO = win( 'o', input );
	    final boolean winX = win( 'x', input );

	    if ( winO ) {
		System.out.println( 'o' );
	    } else if ( winX ) {
		System.out.println( 'x' );
	    } else {
		System.out.println( 'd' );
	    }
	}	
    }

    static boolean win( char ch, String input ) {

	for ( int i = 0; i < 3; i++ ) {
	    int count = 0;
	    for ( int j = 0; j < 3; j++ ) {
		if ( input.charAt( 3 * i + j ) == ch ) {
		    count++;
		}
	    }
	    if ( count == 3 ) {
		return true;
	    }

	    count = 0;
	    for ( int j = 0; j < 3; j++ ) {
		if ( input.charAt( 3 * j + i ) == ch ) {
		    count++;
		}
	    }
	    if ( count == 3 ) {
		return true;
	    }	    
	}

	if ( input.charAt( 3 * 0 + 0 ) == ch &&
	     input.charAt( 3 * 1 + 1 ) == ch &&
	     input.charAt( 3 * 2 + 2 ) == ch ){

	    return true;
	}

	if ( input.charAt( 3 * 2 + 0 ) == ch &&
	     input.charAt( 3 * 1 + 1 ) == ch &&
	     input.charAt( 3 * 0 + 2 ) == ch ){

	    return true;		
	}
	return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;




public class Main {


    public static int CIRCLE_INDEX = 0;

    public static int CROSS_INDEX = 1;


    public static char CIRCLE = 'o';

    public static char CROSS = 'x';

    public static char DRAW = 'd';

    public static void main(String[] args) throws IOException {
        for (String[] result : getResults()) {
            System.out.println(judge(result));
        }
    }

    public static List<String[]> getResults() throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String line;
        List<String[]> results = new ArrayList<>();
        while ((line = reader.readLine()) != null) {
            String[] result = createResult(line);
            results.add(result);
        }
        return results;
    }


    public static class WinPattern {


        private static final Pattern[] winPattern = { Pattern.compile(".*1.*4.*7.*"), Pattern.compile(".*2.*5.*8.*"),
                Pattern.compile(".*3.*6.*9.*"), Pattern.compile(".*1.*2.*3.*"), Pattern.compile(".*4.*5.*6.*"),
                Pattern.compile(".*7.*8.*9.*"), Pattern.compile(".*1.*5.*9.*"), Pattern.compile(".*3.*5.*7.*") };

        public static Pattern[] getWinPattern() {
            return winPattern;
        }
    }

    public static String[] createResult(String input) {
        StringBuilder o = new StringBuilder("");
        StringBuilder x = new StringBuilder("");
        String[] result = new String[2];
        for (int i = 0; i < input.length(); i++) {
            if (input.charAt(i) == CIRCLE) {
                o.append(i + 1);
            } else if (input.charAt(i) == CROSS) {
                x.append(i + 1);
            }
        }

        result[CIRCLE_INDEX] = o.toString();
        result[CROSS_INDEX] = x.toString();

        return result;
    }


    public static char judge(String[] result) {


        for (Pattern p : WinPattern.getWinPattern()) {
            if (p.matcher(result[CIRCLE_INDEX]).matches()) {
                return CIRCLE;
            }
        }

        for (Pattern p : WinPattern.getWinPattern()) {
            if (p.matcher(result[CROSS_INDEX]).matches()) {
                return CROSS;
            }
        }
        return DRAW;
    }

}

import java.io.InputStream;
import java.util.Scanner;





public class Main {

    private static final String RESULT_DRAW = "d";






    public static void main(String[] args) {

        InputStream input = System.in;


        try (Scanner scanner = new Scanner(input)) {
            while (scanner.hasNextLine()) {
                System.out.println(judgeWinner(splitLine(scanner.nextLine())));
            }
        } catch (Exception e) {

        }
    }

    private static String[] splitLine(String line) {
        String[] result = new String[line.length()];

        for (int i = 0; i < line.length(); i++) {
            result[i] = String.valueOf(line.charAt(i));
        }

        return result;
    }

    private static String judgeWinner(String[] line) {
        String result = null;

        result = checkVertical(line);

        if (result != null) {
            return result;
        }


        result = checkHorizontal(line);
        if (result != null) {
            return result;
        }


        result = checkDiagonal(line);
        if (result != null) {
            return result;
        }

        return RESULT_DRAW;
    }

    private static String checkVertical(String[] line) {

        for (int i = 0; i < 3; i++) {
            if (!"s".equals(line[i]) && line[i].equals(line[i + 3])
                    && line[i + 3].equals(line[i + 6])) {
                return line[i];
            }
        }

        return null;
    }

    private static String checkHorizontal(String[] line) {

        for (int i = 0; i < 9; i+=3) {
            if (!"s".equals(line[i]) && line[i].equals(line[i + 1])
                    && line[i + 1].equals(line[i + 2])) {
                return line[i];
            }
        }

        return null;
    }

    private static String checkDiagonal(String[] line) {
        if (!"s".equals(line[0]) && line[0].equals(line[4])
                && line[4].equals(line[8])) {
            return line[0];
        }

        if (!"s".equals(line[2]) && line[2].equals(line[4])
                && line[4].equals(line[6])) {
            return line[2];
        }

        return null;
    }
}

