class IslandCount {
	public int island[][];

	private int height;
	private int width;

	private int getCount;


	IslandCount(int height, int width) {
		this.island = new int[height][width];
		this.height = height;
		this.width = width;
		this.getCount = 0;
	}




	private void initialValue() {


		for (int i = 0; i < height; i++) {
			for (int j = 0; j < width; j++) {
				if (island[i][j] == 1) {








					centerExist(i, j);

					getCount++;

				}
			}
		}

	}




	private void centerExist(int y, int x) {



		island[y][x] = 0;


		if (topExist(y, x)) {
			centerExist(y - 1, x);
		}


		if (bottomExist(y, x)) {
			centerExist(y + 1, x);
		}


		if (rightExist(y, x)) {
			centerExist(y, x + 1);
		}


		if (leftExist(y, x)) {
			centerExist(y, x - 1);
		}
	}




	private boolean topExist(int topY, int topX) {
		boolean ret = false;

		if (topY - 1 >= 0) {

			if (island[topY - 1][topX] == 1) {
				island[topY - 1][topX] = 0;
				ret = true;
			}
		}
		return ret;
	}




	private boolean rightExist(int rightY, int rightX) {
		boolean ret = false;

		if (rightX + 1 < width) {

			if (island[rightY][rightX + 1] == 1) {
				island[rightY][rightX + 1] = 0;
				ret = true;
			}
		}
		return ret;

	}




	private boolean bottomExist(int bottomY, int bottomX) {
		boolean ret = false;


		if (bottomY + 1 < height) {

			if (island[bottomY + 1][bottomX] == 1) {
				island[bottomY + 1][bottomX] = 0;
				ret = true;
			}
		}
		return ret;

	}




	private boolean leftExist(int leftY, int leftX) {
		boolean ret = false;

		if (leftX - 1 >= 0) {

			if (island[leftY][leftX - 1] == 1) {
				island[leftY][leftX - 1] = 0;
				ret = true;
			}
		}
		return ret;

	}






	public int islandCount() {

		initialValue();

		int setC = getCount;
		getCount = 0;
		return setC;


	}

}

