				for(int u=0;u<n;u++)if(!used[u]&&(v==-1||d[u]<d[v]))v=u;
				if(v==-1)break;
				System.out.println(v);
				list[v] = before;
				if(v==g)break;
				used[v]=true;
				for(int u=0;u<n;u++){
