			return this.first - p.first;
		}
	}

	public int dijkstra(int s){
		boolean[] used = new boolean[N];
		int ret = 0;
		PriorityQueue<P> pq = new PriorityQueue<P>();
		pq.add(new P(0,s));
		while(pq.size() > 0){
			P p = pq.poll();
			if(used[p.second])continue;
			used[p.second] = true;
			ret+=p.first;
			for(int next : graph[p.second]){
				pq.add(new P(cost[p.second][next],next));
			}
		}
		return ret;
	}

	@SuppressWarnings("unchecked")
	public void solve() {
		while(true){
			N = nextInt();

			if(N == 0)break;

			M = nextInt();
			a = new int[M];
			b = new int[M];
			d = new int[M];
			graph = new ArrayList[N];
			cost = new int[N][N];
			for(int i = 0;i < N;i++){
				graph[i] = new ArrayList<Integer>();
			}
			for(int i = 0;i < M;i++){
				String[] line = next().split(",");
				a[i] = Integer.parseInt(line[0]);
				b[i] = Integer.parseInt(line[1]);
				d[i] = (Integer.parseInt(line[2]) / 100) - 1;
				cost[a[i]][b[i]] = d[i];
				cost[b[i]][a[i]] = d[i];
				graph[a[i]].add(b[i]);
				graph[b[i]].add(a[i]);
			}
			out.println(dijkstra(0));
		}
	}

	public static void main(String[] args) {
		out.flush();
		new Main().solve();
		out.close();
	}


