						break;
					}
				}

			}
			System.out.println(ans);
			n = sc.nextInt();
		}
	}

	public static boolean connectAndCheck(int[] con, int len, int bef, int aft){
		boolean bRet = true;
		int e = con[0];
		for(int i = 0; i < len; i++){
			if(con[i] == bef){
				con[i] = aft;
			}
			if(e != con[i]){
				bRet = false;
			}
		}
		return bRet;
	}


}

